<!doctype html><html lang="es"><head><meta charset="utf-8"><title><?= h($titulo) ?></title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#1c2540;padding:25px}h1{color:#5428b9}p{font-size:12px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #d5dced;padding:7px;text-align:left;word-wrap:break-word}th{background:#ece8ff}tr:nth-child(even){background:#f7f8ff}.no-print{margin:12px 0}button{padding:10px;border:0;background:#6d39db;color:white}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="window.print()">Imprimir / guardar como PDF</button></div><h1><?= h($titulo) ?></h1><p>DiseñaTuPrenda · Generado: <?= h($fecha) ?> · Registros: <?= count($filas) ?> · Filtro: <?= h($inicio?:'Inicio') ?> a <?= h($fin?:'Hoy') ?></p><table><thead><tr><?php foreach(array_keys($filas[0]??['mensaje'=>'Sin registros']) as $col): ?><th><?= h(ucfirst(str_replace('_',' ',$col))) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($filas as $f): ?><tr><?php foreach($f as $v): ?><td><?= h($v) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></body></html>
